function validate([n, preferences, pairs]) {
  if (!Number.isInteger(n) || n < 2 || n > 500 || n % 2 !== 0) return 'n is an even number from 2 to 500.';
  if (!Array.isArray(preferences) || preferences.length !== n) return 'preferences needs one row per friend.';
  for (let i = 0; i < n; i++) {
    const row = preferences[i];
    if (!Array.isArray(row) || row.length !== n - 1) return `preferences[${i}] must list the other n - 1 friends.`;
    const seen = new Set(row);
    if (seen.size !== n - 1 || seen.has(i) || row.some(v => !Number.isInteger(v) || v < 0 || v >= n)) return `preferences[${i}] must hold every friend except ${i} exactly once.`;
  }
  if (!Array.isArray(pairs) || pairs.length !== n / 2) return 'pairs needs exactly n / 2 pairs.';
  const placed = new Set();
  for (const pair of pairs) {
    if (!Array.isArray(pair) || pair.length !== 2 || pair[0] === pair[1]) return 'Each pair holds two different friends.';
    for (const person of pair) {
      if (!Number.isInteger(person) || person < 0 || person >= n) return 'Pairs use friends from 0 to n - 1.';
      if (placed.has(person)) return 'Every friend belongs to exactly one pair.';
      placed.add(person);
    }
  }
  return null;
}

