function unhappyFriends(n, preferences, pairs) {
  const rank = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let x = 0; x < n; x++) {
    for (let position = 0; position < n - 1; position++) {
      rank[x][preferences[x][position]] = position;
    }
  }

  const partner = new Array(n);
  for (const [a, b] of pairs) {
    partner[a] = b;
    partner[b] = a;
  }

  let unhappy = 0;
  for (let x = 0; x < n; x++) {
    const y = partner[x];
    for (let position = 0; position < rank[x][y]; position++) {
      const u = preferences[x][position];
      const v = partner[u];
      if (rank[u][x] < rank[u][v]) {
        unhappy++;
        break;
      }
    }
  }
  return unhappy;
}

