function unhappyFriends(n, preferences, pairs) {
  const mate = (person) => {
    const pair = pairs.find(p => p[0] === person || p[1] === person);
    return pair[0] === person ? pair[1] : pair[0];
  };
  const likes = (person, a, b) => preferences[person].indexOf(a) < preferences[person].indexOf(b);
  let count = 0;
  for (let x = 0; x < n; x++) {
    const y = mate(x);
    let found = false;
    for (let u = 0; u < n; u++) {
      if (u === x || u === y) continue;
      if (likes(x, u, y) && likes(u, x, mate(u))) found = true;
    }
    if (found) count++;
  }
  return count;
}

