function generate(rand, size) {
  const n = size === 'large' ? 100 : rand() < 0.1 ? 2 : 2 * (2 + Math.floor(rand() * 3));
  const shuffle = (list) => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  const people = shuffle(Array.from({ length: n }, (_, i) => i));
  const pairs = [];
  const partner = new Array(n);
  for (let i = 0; i < n; i += 2) {
    pairs.push([people[i], people[i + 1]]);
    partner[people[i]] = people[i + 1];
    partner[people[i + 1]] = people[i];
  }
  // Some friends rank their partner first, so answers range from none unhappy to most of them.
  const loyal = rand() < 0.3 ? rand() : 0;
  const preferences = [];
  for (let x = 0; x < n; x++) {
    const row = shuffle(Array.from({ length: n }, (_, i) => i).filter(i => i !== x));
    if (rand() < loyal) {
      row.splice(row.indexOf(partner[x]), 1);
      row.unshift(partner[x]);
    }
    preferences.push(row);
  }
  return [n, preferences, pairs];
}
